import { describe, expect, it } from 'vitest';
import { CG_ROUTE_LONG, CG_ROUTE_SHORT } from '../story/commonGroundState.ts';
import { CG_FIXED_SOCKET, evaluateOfferedSpan, WORKER_BODY_HEIGHT } from '../story/commonGroundRoute.ts';
const flat = { revision: 't', isSupported: (p: any) => Math.abs(p.y - 51.05) < 0.001 };
describe('authored routes vs the fixed reference', () => {
  it('reports', () => {
    for (const [name, route] of [['long', CG_ROUTE_LONG], ['short', CG_ROUTE_SHORT]] as const) {
      const r = evaluateOfferedSpan(route as any, { fixed: CG_FIXED_SOCKET, held: null }, flat, { extraSolids: [], bodyHeight: WORKER_BODY_HEIGHT });
      console.log(name, JSON.stringify(r));
    }
    // Densified: samples every 0.25 units along the authored long route.
    const dense: any[] = [];
    for (let i = 1; i < CG_ROUTE_LONG.length; i++) {
      const a = CG_ROUTE_LONG[i - 1], b = CG_ROUTE_LONG[i];
      const steps = Math.ceil(Math.hypot(b.x - a.x, b.z - a.z) / 0.25);
      for (let s = 0; s < steps; s++) dense.push({ x: a.x + (b.x - a.x) * s / steps, y: a.y, z: a.z + (b.z - a.z) * s / steps });
    }
    dense.push(CG_ROUTE_LONG[CG_ROUTE_LONG.length - 1]);
    const d = evaluateOfferedSpan(dense, { fixed: CG_FIXED_SOCKET, held: null }, flat, { extraSolids: [], bodyHeight: WORKER_BODY_HEIGHT });
    console.log('dense-long', JSON.stringify(d), dense.length, JSON.stringify(dense[d.firstUnsupportedIndex ?? 0]));
    expect(true).toBe(true);
  });
});
